mkitem!{mkimpl!{impl < 'a , Cx : PatCx > fmt :: Debug for PlaceCtxt < 'a , Cx > { fn fmt (& self , fmt : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt . debug_struct ("PlaceCtxt") . field ("ty" , self . ty) . finish () } }}}
mkitem!{mkimpl!{impl < 'a , Cx : PatCx > PlaceCtxt < 'a , Cx > { fn ctor_arity (& self , ctor : & Constructor < Cx >) -> usize { self . cx . ctor_arity (ctor , self . ty) } fn wild_from_ctor (& self , ctor : Constructor < Cx >) -> WitnessPat < Cx > { WitnessPat :: wild_from_ctor (self . cx , ctor , self . ty . clone ()) } }}}
mkitem!{mkenum!{# [doc = " Track whether a given place (aka column) is known to contain a valid value or not."] # [derive (Debug , Copy , Clone , PartialEq , Eq)] pub enum PlaceValidity { ValidOnly , MaybeInvalid , }}}
mkitem!{mkimpl!{impl PlaceValidity { pub fn from_bool (is_valid_only : bool) -> Self { if is_valid_only { ValidOnly } else { MaybeInvalid } } fn is_known_valid (self) -> bool { matches ! (self , ValidOnly) } # [doc = " If the place has validity given by `self` and we read that the value at the place has"] # [doc = " constructor `ctor`, this computes what we can assume about the validity of the constructor"] # [doc = " fields."] # [doc = ""] # [doc = " Pending further opsem decisions, the current behavior is: validity is preserved, except"] # [doc = " inside `&` and union fields where validity is reset to `MaybeInvalid`."] fn specialize < Cx : PatCx > (self , ctor : & Constructor < Cx >) -> Self { if matches ! (ctor , Constructor :: Ref | Constructor :: DerefPattern (_) | Constructor :: UnionField) { MaybeInvalid } else { self } } }}}
mkitem!{mkimpl!{impl fmt :: Display for PlaceValidity { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { let s = match self { ValidOnly => "✓" , MaybeInvalid => "?" , } ; write ! (f , "{s}") } }}}
mkitem!{mkstruct!{# [doc = " Data about a place under investigation. Its methods contain a lot of the logic used to analyze"] # [doc = " the constructors in the matrix."] struct PlaceInfo < Cx : PatCx > { # [doc = " The type of the place."] ty : Cx :: Ty , # [doc = " Whether the place is a private uninhabited field. If so we skip this field during analysis"] # [doc = " so that we don't observe its emptiness."] private_uninhabited : bool , # [doc = " Whether the place is known to contain valid data."] validity : PlaceValidity , # [doc = " Whether the place is the scrutinee itself or a subplace of it."] is_scrutinee : bool , }}}
mkitem!{mkimpl!{impl < Cx : PatCx > PlaceInfo < Cx > { # [doc = " Given a constructor for the current place, we return one `PlaceInfo` for each field of the"] # [doc = " constructor."] fn specialize (& self , cx : & Cx , ctor : & Constructor < Cx > ,) -> impl Iterator < Item = Self > + ExactSizeIterator { let ctor_sub_tys = cx . ctor_sub_tys (ctor , & self . ty) ; let ctor_sub_validity = self . validity . specialize (ctor) ; ctor_sub_tys . map (move | (ty , PrivateUninhabitedField (private_uninhabited)) | PlaceInfo { ty , private_uninhabited , validity : ctor_sub_validity , is_scrutinee : false , }) } # [doc = " This analyzes a column of constructors corresponding to the current place. It returns a pair"] # [doc = " `(split_ctors, missing_ctors)`."] # [doc = ""] # [doc = " `split_ctors` is a splitted list of constructors that cover the whole type. This will be"] # [doc = " used to specialize the matrix."] # [doc = ""] # [doc = " `missing_ctors` is a list of the constructors not found in the column, for reporting"] # [doc = " purposes."] fn split_column_ctors < 'a > (& self , cx : & Cx , ctors : impl Iterator < Item = & 'a Constructor < Cx > > + Clone ,) -> Result < (SmallVec < [Constructor < Cx > ; 1] > , Vec < Constructor < Cx > >) , Cx :: Error > where Cx : 'a , { debug ! (? self . ty) ; if self . private_uninhabited { return Ok ((smallvec ! [Constructor :: PrivateUninhabited] , vec ! [])) ; } if ctors . clone () . any (| c | matches ! (c , Constructor :: Or)) { return Ok ((smallvec ! [Constructor :: Or] , vec ! [])) ; } let ctors_for_ty = cx . ctors_for_ty (& self . ty) ? ; debug ! (? ctors_for_ty) ; let is_toplevel_exception = self . is_scrutinee && matches ! (ctors_for_ty , ConstructorSet :: NoConstructors) ; let empty_arms_are_unreachable = self . validity . is_known_valid () && (is_toplevel_exception || cx . is_exhaustive_patterns_feature_on ()) ; let can_omit_empty_arms = self . validity . is_known_valid () || is_toplevel_exception || cx . is_exhaustive_patterns_feature_on () ; let mut split_set = ctors_for_ty . split (ctors) ; debug ! (? split_set) ; let all_missing = split_set . present . is_empty () ; let mut split_ctors = split_set . present ; if ! (split_set . missing . is_empty () && (split_set . missing_empty . is_empty () || empty_arms_are_unreachable)) { split_ctors . push (Constructor :: Missing) ; } let mut missing_ctors = split_set . missing ; if ! can_omit_empty_arms { missing_ctors . append (& mut split_set . missing_empty) ; } let report_individual_missing_ctors = self . is_scrutinee || ! all_missing ; if ! missing_ctors . is_empty () && ! report_individual_missing_ctors { missing_ctors = vec ! [Constructor :: Wildcard] ; } else if missing_ctors . iter () . any (| c | c . is_non_exhaustive ()) && ! cx . exhaustive_witnesses () { missing_ctors = vec ! [Constructor :: NonExhaustive] ; } Ok ((split_ctors , missing_ctors)) } }}}
mkitem!{mkimpl!{impl < Cx : PatCx > Clone for PlaceInfo < Cx > { fn clone (& self) -> Self { Self { ty : self . ty . clone () , private_uninhabited : self . private_uninhabited , validity : self . validity , is_scrutinee : self . is_scrutinee , } } }}}
mkitem!{mkstruct!{# [doc = " Represents a pattern-tuple under investigation."] struct PatStack < 'p , Cx : PatCx > { pats : SmallVec < [PatOrWild < 'p , Cx > ; 2] > , # [doc = " Sometimes we know that as far as this row is concerned, the current case is already handled"] # [doc = " by a different, more general, case. When the case is irrelevant for all rows this allows us"] # [doc = " to skip a case entirely. This is purely an optimization. See at the top for details."] relevant : bool , }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > Clone for PatStack < 'p , Cx > { fn clone (& self) -> Self { Self { pats : self . pats . clone () , relevant : self . relevant } } }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > PatStack < 'p , Cx > { fn from_pattern (pat : & 'p DeconstructedPat < Cx >) -> Self { PatStack { pats : smallvec ! [PatOrWild :: Pat (pat)] , relevant : true } } fn len (& self) -> usize { self . pats . len () } fn head (& self) -> PatOrWild < 'p , Cx > { self . pats [0] } fn iter (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > { self . pats . iter () . copied () } fn expand_or_pat (& self) -> impl Iterator < Item = PatStack < 'p , Cx > > { self . head () . expand_or_pat () . into_iter () . map (move | pat | { let mut new = self . clone () ; new . pats [0] = pat ; new }) } # [doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] # [doc = " Only call if `ctor.is_covered_by(self.head().ctor())` is true."] fn pop_head_constructor (& self , cx : & Cx , ctor : & Constructor < Cx > , ctor_arity : usize , ctor_is_relevant : bool ,) -> Result < PatStack < 'p , Cx > , Cx :: Error > { let head_pat = self . head () ; if head_pat . as_pat () . is_some_and (| pat | pat . arity () > ctor_arity) { return Err (cx . bug (format_args ! ("uncaught type error: pattern {:?} has inconsistent arity (expected arity <= {ctor_arity})" , head_pat . as_pat () . unwrap ()))) ; } let mut new_pats = head_pat . specialize (ctor , ctor_arity) ; new_pats . extend_from_slice (& self . pats [1 ..]) ; let ctor_is_relevant = ! matches ! (self . head () . ctor () , Constructor :: Wildcard) || ctor_is_relevant ; Ok (PatStack { pats : new_pats , relevant : self . relevant && ctor_is_relevant }) } }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > fmt :: Debug for PatStack < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "+") ? ; for pat in self . iter () { write ! (f , " {pat:?} +") ? ; } Ok (()) } }}}
mkitem!{mkstruct!{# [doc = " A row of the matrix."] # [derive (Clone)] struct MatrixRow < 'p , Cx : PatCx > { pats : PatStack < 'p , Cx > , # [doc = " Whether the original arm had a guard. This is inherited when specializing."] is_under_guard : bool , # [doc = " When we specialize, we remember which row of the original matrix produced a given row of the"] # [doc = " specialized matrix. When we unspecialize, we use this to propagate usefulness back up the"] # [doc = " callstack. On creation, this stores the index of the original match arm."] parent_row : usize , # [doc = " False when the matrix is just built. This is set to `true` by"] # [doc = " [`compute_exhaustiveness_and_usefulness`] if the arm is found to be useful."] # [doc = " This is reset to `false` when specializing."] useful : bool , # [doc = " Tracks some rows above this one that have an intersection with this one, i.e. such that"] # [doc = " there is a value that matches both rows."] # [doc = " Because of relevancy we may miss some intersections. The intersections we do find are"] # [doc = " correct. In other words, this is an underapproximation of the real set of intersections."] # [doc = ""] # [doc = " For example:"] # [doc = " ```rust,ignore(illustrative)"] # [doc = " match ... {"] # [doc = "     (true, _, _) => {} // `intersects_at_least = []`"] # [doc = "     (_, true, 0..=10) => {} // `intersects_at_least = []`"] # [doc = "     (_, true, 5..15) => {} // `intersects_at_least = [1]`"] # [doc = " }"] # [doc = " ```"] # [doc = " Here the `(true, true)` case is irrelevant. Since we skip it, we will not detect that row 0"] # [doc = " intersects rows 1 and 2."] intersects_at_least : DenseBitSet < usize > , # [doc = " Whether the head pattern is a branch (see definition of \"branch pattern\" at"] # [doc = " [`BranchPatUsefulness`])"] head_is_branch : bool , }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > MatrixRow < 'p , Cx > { fn new (arm : & MatchArm < 'p , Cx > , arm_id : usize) -> Self { MatrixRow { pats : PatStack :: from_pattern (arm . pat) , parent_row : arm_id , is_under_guard : arm . has_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : true , } } fn len (& self) -> usize { self . pats . len () } fn head (& self) -> PatOrWild < 'p , Cx > { self . pats . head () } fn iter (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > { self . pats . iter () } fn expand_or_pat (& self , parent_row : usize) -> impl Iterator < Item = MatrixRow < 'p , Cx > > { let is_or_pat = self . pats . head () . is_or_pat () ; self . pats . expand_or_pat () . map (move | patstack | MatrixRow { pats : patstack , parent_row , is_under_guard : self . is_under_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : is_or_pat , }) } # [doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] # [doc = " Only call if `ctor.is_covered_by(self.head().ctor())` is true."] fn pop_head_constructor (& self , cx : & Cx , ctor : & Constructor < Cx > , ctor_arity : usize , ctor_is_relevant : bool , parent_row : usize ,) -> Result < MatrixRow < 'p , Cx > , Cx :: Error > { Ok (MatrixRow { pats : self . pats . pop_head_constructor (cx , ctor , ctor_arity , ctor_is_relevant) ? , parent_row , is_under_guard : self . is_under_guard , useful : false , intersects_at_least : DenseBitSet :: new_empty (0) , head_is_branch : false , }) } }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > fmt :: Debug for MatrixRow < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . pats . fmt (f) } }}}
mkitem!{mkstruct!{# [doc = " A 2D matrix. Represents a list of pattern-tuples under investigation."] # [doc = ""] # [doc = " Invariant: each row must have the same length, and each column must have the same type."] # [doc = ""] # [doc = " Invariant: the first column must not contain or-patterns. This is handled by"] # [doc = " [`Matrix::push`]."] # [doc = ""] # [doc = " In fact each column corresponds to a place inside the scrutinee of the match. E.g. after"] # [doc = " specializing `(,)` and `Some` on a pattern of type `(Option<u32>, bool)`, the first column of"] # [doc = " the matrix will correspond to `scrutinee.0.Some.0` and the second column to `scrutinee.1`."] # [derive (Clone)] struct Matrix < 'p , Cx : PatCx > { # [doc = " Vector of rows. The rows must form a rectangular 2D array. Moreover, all the patterns of"] # [doc = " each column must have the same type. Each column corresponds to a place within the"] # [doc = " scrutinee."] rows : Vec < MatrixRow < 'p , Cx > > , # [doc = " Track info about each place. Each place corresponds to a column in `rows`, and their types"] # [doc = " must match."] place_info : SmallVec < [PlaceInfo < Cx > ; 2] > , # [doc = " Track whether the virtual wildcard row used to compute exhaustiveness is relevant. See top"] # [doc = " of the file for details on relevancy."] wildcard_row_is_relevant : bool , }}}
mkitem!{mkimpl!{impl < 'p , Cx : PatCx > Matrix < 'p , Cx > { # [doc = " Pushes a new row to the matrix. Internal method, prefer [`Matrix::new`]."] fn push (& mut self , mut row : MatrixRow < 'p , Cx >) { row . intersects_at_least = DenseBitSet :: new_empty (self . rows . len ()) ; self . rows . push (row) ; } # [doc = " Build a new matrix from an iterator of `MatchArm`s."] fn new (arms : & [MatchArm < 'p , Cx >] , scrut_ty : Cx :: Ty , scrut_validity : PlaceValidity) -> Self { let place_info = PlaceInfo { ty : scrut_ty , private_uninhabited : false , validity : scrut_validity , is_scrutinee : true , } ; let mut matrix = Matrix { rows : Vec :: with_capacity (arms . len ()) , place_info : smallvec ! [place_info] , wildcard_row_is_relevant : true , } ; for (arm_id , arm) in arms . iter () . enumerate () { matrix . push (MatrixRow :: new (arm , arm_id)) ; } matrix } fn head_place (& self) -> Option < & PlaceInfo < Cx > > { self . place_info . first () } fn column_count (& self) -> usize { self . place_info . len () } fn rows (& self ,) -> impl Iterator < Item = & MatrixRow < 'p , Cx > > + Clone + DoubleEndedIterator + ExactSizeIterator { self . rows . iter () } fn rows_mut (& mut self ,) -> impl Iterator < Item = & mut MatrixRow < 'p , Cx > > + DoubleEndedIterator + ExactSizeIterator { self . rows . iter_mut () } # [doc = " Iterate over the first pattern of each row."] fn heads (& self) -> impl Iterator < Item = PatOrWild < 'p , Cx > > + Clone { self . rows () . map (| r | r . head ()) } # [doc = " This computes `specialize(ctor, self)`. See top of the file for explanations."] fn specialize_constructor (& self , pcx : & PlaceCtxt < '_ , Cx > , ctor : & Constructor < Cx > , ctor_is_relevant : bool ,) -> Result < Matrix < 'p , Cx > , Cx :: Error > { if matches ! (ctor , Constructor :: Or) { let mut matrix = Matrix { rows : Vec :: new () , place_info : self . place_info . clone () , wildcard_row_is_relevant : self . wildcard_row_is_relevant , } ; for (i , row) in self . rows () . enumerate () { for new_row in row . expand_or_pat (i) { matrix . push (new_row) ; } } Ok (matrix) } else { let subfield_place_info = self . place_info [0] . specialize (pcx . cx , ctor) ; let arity = subfield_place_info . len () ; let specialized_place_info = subfield_place_info . chain (self . place_info [1 ..] . iter () . cloned ()) . collect () ; let mut matrix = Matrix { rows : Vec :: new () , place_info : specialized_place_info , wildcard_row_is_relevant : self . wildcard_row_is_relevant && ctor_is_relevant , } ; for (i , row) in self . rows () . enumerate () { if ctor . is_covered_by (pcx . cx , row . head () . ctor ()) ? { let new_row = row . pop_head_constructor (pcx . cx , ctor , arity , ctor_is_relevant , i) ? ; matrix . push (new_row) ; } } Ok (matrix) } } # [doc = " Recover row usefulness and intersection information from a processed specialized matrix."] # [doc = " `specialized` must come from `self.specialize_constructor`."] fn unspecialize (& mut self , specialized : Self) { for child_row in specialized . rows () { let parent_row_id = child_row . parent_row ; let parent_row = & mut self . rows [parent_row_id] ; parent_row . useful |= child_row . useful ; for child_intersection in child_row . intersects_at_least . iter () { let parent_intersection = specialized . rows [child_intersection] . parent_row ; if parent_intersection != parent_row_id { parent_row . intersects_at_least . insert (parent_intersection) ; } } } } }}}
mkitem!{mkimpl!{# [doc = " Pretty-printer for matrices of patterns, example:"] # [doc = ""] # [doc = " ```text"] # [doc = " + _     + []                +"] # [doc = " + true  + [First]           +"] # [doc = " + true  + [Second(true)]    +"] # [doc = " + false + [_]               +"] # [doc = " + _     + [_, _, tail @ ..] +"] # [doc = " | ✓     | ?                 | // validity"] # [doc = " ```"] impl < 'p , Cx : PatCx > fmt :: Debug for Matrix < 'p , Cx > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { write ! (f , "\n") ? ; let mut pretty_printed_matrix : Vec < Vec < String > > = self . rows . iter () . map (| row | row . iter () . map (| pat | format ! ("{pat:?}")) . collect ()) . collect () ; pretty_printed_matrix . push (self . place_info . iter () . map (| place | format ! ("{}" , place . validity)) . collect ()) ; let column_count = self . column_count () ; assert ! (self . rows . iter () . all (| row | row . len () == column_count)) ; assert ! (self . place_info . len () == column_count) ; let column_widths : Vec < usize > = (0 .. column_count) . map (| col | pretty_printed_matrix . iter () . map (| row | row [col] . len ()) . max () . unwrap_or (0)) . collect () ; for (row_i , row) in pretty_printed_matrix . into_iter () . enumerate () { let is_validity_row = row_i == self . rows . len () ; let sep = if is_validity_row { "|" } else { "+" } ; write ! (f , "{sep}") ? ; for (column , pat_str) in row . into_iter () . enumerate () { write ! (f , " ") ? ; write ! (f , "{:1$}" , pat_str , column_widths [column]) ? ; write ! (f , " {sep}") ? ; } if is_validity_row { write ! (f , " // validity") ? ; } write ! (f , "\n") ? ; } Ok (()) } }}}
mkitem!{mkstruct!{# [doc = " A witness-tuple of non-exhaustiveness for error reporting, represented as a list of patterns (in"] # [doc = " reverse order of construction)."] # [doc = ""] # [doc = " This mirrors `PatStack`: they function similarly, except `PatStack` contains user patterns we"] # [doc = " are inspecting, and `WitnessStack` contains witnesses we are constructing."] # [doc = " FIXME(Nadrieril): use the same order of patterns for both."] # [doc = ""] # [doc = " A `WitnessStack` should have the same types and length as the `PatStack`s we are inspecting"] # [doc = " (except we store the patterns in reverse order). The same way `PatStack` starts with length 1,"] # [doc = " at the end of the algorithm this will have length 1. In the middle of the algorithm, it can"] # [doc = " contain multiple patterns."] # [doc = ""] # [doc = " For example, if we are constructing a witness for the match against"] # [doc = ""] # [doc = " ```compile_fail,E0004"] # [doc = " struct Pair(Option<(u32, u32)>, bool);"] # [doc = " # fn foo(p: Pair) {"] # [doc = " match p {"] # [doc = "    Pair(None, _) => {}"] # [doc = "    Pair(_, false) => {}"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " We'll perform the following steps (among others):"] # [doc = " ```text"] # [doc = " - Start with a matrix representing the match"] # [doc = "     `PatStack(vec![Pair(None, _)])`"] # [doc = "     `PatStack(vec![Pair(_, false)])`"] # [doc = " - Specialize with `Pair`"] # [doc = "     `PatStack(vec![None, _])`"] # [doc = "     `PatStack(vec![_, false])`"] # [doc = " - Specialize with `Some`"] # [doc = "     `PatStack(vec![_, false])`"] # [doc = " - Specialize with `_`"] # [doc = "     `PatStack(vec![false])`"] # [doc = " - Specialize with `true`"] # [doc = "     // no patstacks left"] # [doc = " - This is a non-exhaustive match: we have the empty witness stack as a witness."] # [doc = "     `WitnessStack(vec![])`"] # [doc = " - Apply `true`"] # [doc = "     `WitnessStack(vec![true])`"] # [doc = " - Apply `_`"] # [doc = "     `WitnessStack(vec![true, _])`"] # [doc = " - Apply `Some`"] # [doc = "     `WitnessStack(vec![true, Some(_)])`"] # [doc = " - Apply `Pair`"] # [doc = "     `WitnessStack(vec![Pair(Some(_), true)])`"] # [doc = " ```"] # [doc = ""] # [doc = " The final `Pair(Some(_), true)` is then the resulting witness."] # [doc = ""] # [doc = " See the top of the file for more detailed explanations and examples."] # [derive (Debug)] struct WitnessStack < Cx : PatCx > (Vec < WitnessPat < Cx > >) ;}}
mkitem!{mkimpl!{impl < Cx : PatCx > Clone for WitnessStack < Cx > { fn clone (& self) -> Self { Self (self . 0 . clone ()) } }}}
